def clean_text(s):
    if s is None:
        return ""
    s = htmlmod.unescape(str(s))
    s = re.sub(r"<[^>]+>", " ", s)
    s = re.sub(r"\s+", " ", s).strip()
    return s

ML_SHORT_HOSTS = {"meli.la", "www.meli.la", "meli.re", "www.meli.re"}
SHOPEE_SHORT_HOSTS = {
    "shope.ee", "www.shope.ee",
    "shp.ee", "www.shp.ee", "br.shp.ee",
}
AMAZON_AFFILIATE_SHORT_HOSTS = {
    "amzn.to", "www.amzn.to",
    "link.amazon", "www.link.amazon",
    "amzlinks.in", "www.amzlinks.in",
}
AMAZON_SHARE_SHORT_HOSTS = {"a.co", "www.a.co"}
AMAZON_SHORT_HOSTS = AMAZON_AFFILIATE_SHORT_HOSTS | AMAZON_SHARE_SHORT_HOSTS


def _safe_https_host(url):
    try:
        parsed = urlparse(url)
        host = (parsed.hostname or "").lower()
        if parsed.scheme.lower() != "https" or not host or parsed.username or parsed.password:
            return ""
        if parsed.port not in (None, 443):
            return ""
        return host
    except Exception:
        return ""


def is_allowed_product_url(url, platform="mercadolivre"):
    host = _safe_https_host(url)
    if not host:
        return False
    if platform == "shopee":
        return host == "shopee.com.br" or host.endswith(".shopee.com.br")
    if platform == "amazon":
        return host == "amazon.com.br" or host.endswith(".amazon.com.br")
    return host == "mercadolivre.com.br" or host.endswith(".mercadolivre.com.br") or host == "mercadolivre.com" or host.endswith(".mercadolivre.com")


def is_allowed_product_input_url(url, platform="mercadolivre"):
    host = _safe_https_host(url)
    if not host:
        return False
    if platform == "shopee":
        return is_allowed_product_url(url, platform) or host in SHOPEE_SHORT_HOSTS
    if platform == "amazon":
        return is_allowed_product_url(url, platform) or host in AMAZON_SHORT_HOSTS
    return is_allowed_product_url(url, platform) or host in ML_SHORT_HOSTS


def extract_product_input_url(value):
    """Accept a bare URL or a mobile share message containing one HTTPS link."""
    value = htmlmod.unescape(str(value or "")).strip()
    match = re.search(r"https://[^\s<>\"']+", value, re.I)
    if not match:
        return value
    return match.group(0).rstrip(".,;:!?)]}>")


def is_affiliate_product_url(url, platform="mercadolivre"):
    if not is_allowed_product_input_url(url, platform):
        return False
    parsed = urlparse(url)
    host = (parsed.hostname or "").lower()
    path = parsed.path.lower()
    query = {key.lower(): value for key, value in parse_qsl(parsed.query, keep_blank_values=True)}
    if platform == "shopee":
        return (
            host in SHOPEE_SHORT_HOSTS or host == "s.shopee.com.br"
            or query.get("utm_medium", "").lower() == "affiliates"
            or query.get("mmp_pid", "").lower().startswith("an_")
            or query.get("utm_source", "").lower().startswith("an_")
        )
    if platform == "amazon":
        return (
            host in AMAZON_AFFILIATE_SHORT_HOSTS
            or bool(query.get("tag"))
            or bool(query.get("linkcode"))
            or bool(query.get("ascsubtag"))
        )
    return (
        host in ML_SHORT_HOSTS or path.startswith("/sec/") or path.startswith("/social/")
        or "matt_word" in query or "matt_tool" in query or "ref" in query
    )


def canonicalize_product_url(url, platform="mercadolivre"):
    if not is_allowed_product_url(url, platform):
        return ""
    parsed = urlparse(url)
    path = parsed.path
    if platform == "shopee":
        if not (re.search(r"-i\.\d+\.\d+", path, re.I) or re.search(r"/product/\d+/\d+", path, re.I)):
            return ""
        # Item e loja já fazem parte do caminho; parâmetros de afiliado/rastreamento não são necessários.
        query = ""
    elif platform == "amazon":
        asin = extract_amazon_asin(url)
        if not asin:
            return ""
        path = f"/dp/{asin}"
        query = ""
    else:
        if not re.search(r"(?:MLB-?\d{6,}|/p/MLB\d{6,}|/up/MLBU\d{6,})", path, re.I):
            return ""
        keep = {"item_id", "variation", "quantity"}
        query = urlencode([(key, value) for key, value in parse_qsl(parsed.query, keep_blank_values=True)
                           if key.lower() in keep])
    return urlunparse(("https", parsed.netloc.lower(), path, "", query, ""))


def extract_amazon_asin(url, source=""):
    """Find the 10-character Amazon product identifier in common Brazil URLs."""
    candidates = [str(url or ""), str(source or "")]
    patterns = (
        r"/(?:dp|gp/product|gp/aw/d)/([A-Z0-9]{10})(?:[/?]|$)",
        r'["\'](?:asin|ASIN|creativeASIN)["\']\s*[:=]\s*["\']([A-Z0-9]{10})',
    )
    for candidate in candidates:
        for pattern in patterns:
            match = re.search(pattern, candidate, re.I)
            if match:
                return match.group(1).upper()
    return ""


def shopee_product_ids(url):
    """Return (shop_id, item_id) from every public Shopee product URL format."""
    if not is_allowed_product_url(url, "shopee"):
        return None
    path = urlparse(url).path
    for pattern in (
        r"-i\.(\d+)\.(\d+)(?:/|$)",
        r"/product/(\d+)/(\d+)(?:/|$)",
        r"/[^/]+/(\d+)/(\d+)(?:/|$)",
    ):
        match = re.search(pattern, path, re.I)
        if match:
            return match.group(1), match.group(2)
    return None

def is_allowed_image_url(url):
    try:
        host = (urlparse(url).hostname or "").lower()
    except Exception:
        return False
    return (
        host == "mlstatic.com" or host.endswith(".mlstatic.com")
        or host == "mercadolivre.com.br" or host.endswith(".mercadolivre.com.br")
        or host == "mercadolivre.com" or host.endswith(".mercadolivre.com")
        or host == "susercontent.com" or host.endswith(".susercontent.com")
        or host == "shopee.com.br" or host.endswith(".shopee.com.br")
        or host == "media-amazon.com" or host.endswith(".media-amazon.com")
        or host == "ssl-images-amazon.com" or host.endswith(".ssl-images-amazon.com")
        or host == "amazon.com.br" or host.endswith(".amazon.com.br")
    )

def detect_image_content_type(body):
    if body.startswith(b"\xff\xd8\xff"):
        return "image/jpeg"
    if body.startswith(b"\x89PNG\r\n\x1a\n"):
        return "image/png"
    if body.startswith((b"GIF87a", b"GIF89a")):
        return "image/gif"
    if len(body) >= 12 and body[:4] == b"RIFF" and body[8:12] == b"WEBP":
        return "image/webp"
    if len(body) >= 12 and body[4:8] == b"ftyp" and body[8:12] in (b"avif", b"avis", b"heic", b"heix"):
        return "image/avif" if body[8:12] in (b"avif", b"avis") else "image/heic"
    return ""

class SafeRedirectHandler(HTTPRedirectHandler):
    def __init__(self, validator):
        super().__init__()
        self.validator = validator

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        target = urljoin(req.full_url, newurl)
        if not self.validator(target):
            raise URLError("O link tentou redirecionar para um endereço não permitido.")
        return super().redirect_request(req, fp, code, msg, headers, target)


def http_get(url, accept="text/html,application/xhtml+xml,application/json;q=0.9,*/*;q=0.8", timeout=18, extra_headers=None, redirect_validator=None):
    request_headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/151.0 Safari/537.36",
        "Accept": accept,
        "Accept-Language": "pt-BR,pt;q=0.9,en;q=0.7",
        "Cache-Control": "no-cache",
        "Pragma": "no-cache",
    }
    request_headers.update(extra_headers or {})
    req = Request(url, headers=request_headers)
    opener = build_opener(SafeRedirectHandler(redirect_validator)) if redirect_validator else None
    response = opener.open(req, timeout=timeout) if opener else urlopen(req, timeout=timeout)
    with response as r:
        return r.geturl(), r.headers, r.read()

def http_get_json(url, timeout=18, extra_headers=None):
    final_url, headers, body = http_get(url, accept="application/json", extra_headers=extra_headers)
    return final_url, json.loads(body.decode("utf-8", errors="strict"))

def extract_item_id(url, source=""):
    """Find a marketplace listing id (MLB123 or MLB-123), not a catalog /p/ id."""
    candidates = [url]
    candidates.extend(re.findall(r'(?i)(?:item[_-]?id|id)["\']?\s*[:=]\s*["\']?(MLB-?\d{6,})', source))
    candidates.extend(re.findall(r'(?i)(MLB-\d{6,})', source))
    for value in candidates:
        text = str(value or "")
        if re.search(r"(?i)/p/MLB\d+", text):
            text = re.sub(r"(?i)/p/MLB\d+", "", text)
        match = re.search(r"(?i)MLB-?\d{6,}", text)
        if match:
            return match.group(0).replace("-", "").upper()
    return ""

def extract_catalog_id(url):
    match = re.search(r"(?i)/p/(MLB\d{6,})", str(url or ""))
    return match.group(1).upper() if match else ""

def extract_user_product_id(url):
    match = re.search(r"(?i)/up/(MLBU\d{6,})", str(url or ""))
    return match.group(1).upper() if match else ""

def title_from_product_url(url):
    path = urlparse(url).path.strip("/")
    slug = path.split("/up/", 1)[0] if "/up/" in path.lower() else ""
    return clean_text(slug.replace("-", " ")).title() if slug else ""

def title_from_shopee_url(url):
    path = urlparse(url).path.strip("/")
    slug = re.sub(r"-i\.\d+\.\d+.*$", "", path, flags=re.I)
    return clean_text(slug.replace("-", " ")).title() if slug and slug.lower() not in ("product", "") else ""

def parse_catalog_api(catalog_id, access_token):
    auth = {"Authorization": f"Bearer {access_token}"}
    product_result = parse_catalog_details_api(catalog_id, access_token)
    _, listing = http_get_json(
        f"https://api.mercadolibre.com/products/{quote(catalog_id)}/items",
        extra_headers=auth,
    )
    candidates = listing.get("results", []) if isinstance(listing, dict) else listing
    offers = [x for x in (candidates or []) if isinstance(x, dict) and first_num(x.get("price")) is not None]
    if not offers:
        raise ValueError("Nenhuma oferta ativa foi encontrada para esse produto de catálogo.")
    offer = min(offers, key=lambda x: first_num(x.get("price")))
    price = first_num(offer.get("price"))
    old = first_num(offer.get("original_price"))
    if old is not None and price is not None and old <= price:
        old = None
    available = offer.get("available_quantity")
    product_result.update({
        "price": price,
        "other_payment_price": price,
        "original_price": old,
        "availability": "Disponível" if available is None or available > 0 else "Sem estoque",
        "free_shipping": bool((offer.get("shipping") or {}).get("free_shipping")),
        "category": product_result.get("category") or clean_text(offer.get("category_id")),
        "item_id": offer.get("item_id") or "",
    })
    product_result["summary"] = make_summary(
        product_result.get("title", ""), product_result.get("description", ""),
        product_result.get("brand", ""), price, old,
    )
    return product_result


def parse_catalog_details_api(catalog_id, access_token):
    """Load catalog facts without requiring the listing/offers endpoint."""
    _, product = http_get_json(
        f"https://api.mercadolibre.com/products/{quote(catalog_id)}",
        extra_headers={"Authorization": f"Bearer {access_token}"},
    )
    if not isinstance(product, dict) or not product.get("name"):
        raise ValueError("A API do Mercado Livre não retornou os dados do catálogo.")

    images = []
    for picture in product.get("pictures") or []:
        if not isinstance(picture, dict):
            continue
        picture_url = picture.get("secure_url") or picture.get("url") or ""
        if picture_url and picture_url not in images:
            images.append(picture_url)

    brand = ""
    features = []
    for feature in product.get("main_features") or []:
        value = clean_text(feature.get("text")) if isinstance(feature, dict) else ""
        if value and value not in features:
            features.append(compact_feature(value))
    ignored = {"GTIN", "EMPTY_GTIN_REASON", "SELLER_SKU", "ITEM_CONDITION"}
    for attr in product.get("attributes") or []:
        if not isinstance(attr, dict):
            continue
        attr_id = clean_text(attr.get("id")).upper()
        name = clean_text(attr.get("name"))
        value = clean_text(attr.get("value_name"))
        if attr_id == "BRAND" and value:
            brand = value
        if attr_id not in ignored and name and value and len(name) < 40 and len(value) < 80:
            text = compact_feature(f"{name}: {value}")
            if text not in features:
                features.append(text)
        if len(features) >= 8:
            break
    features = features[:5]
    title = clean_text(product.get("name"))
    description = " ".join(features)
    return {
        "ok": True, "title": title, "price": None, "original_price": None,
        "other_payment_price": None, "pix_price": None,
        "image": images[0] if images else "", "images": images,
        "description": description, "brand": brand,
        "category": clean_text(product.get("domain_id")), "availability": "Não informado",
        "rating": "", "free_shipping": False, "benefits": features,
        "summary": make_summary(title, description, brand, None, None),
        "final_url": product.get("permalink") or "", "catalog_id": catalog_id,
        "item_id": "",
        "warning": "Características carregadas pelo catálogo oficial do Mercado Livre.",
    }

def find_catalog_offers(catalog_id, access_token):
    _, payload = http_get_json(
        f"https://api.mercadolibre.com/products/{quote(catalog_id)}/items",
        extra_headers={"Authorization": f"Bearer {access_token}"},
    )
    results = payload.get("results", []) if isinstance(payload, dict) else []
    offers = []
    for item in results:
        if not isinstance(item, dict):
            continue
        item_id = clean_text(item.get("item_id") or item.get("id"))
        price = first_num(item.get("price"))
        if not item_id or price is None:
            continue
        old = first_num(item.get("original_price"))
        shipping = item.get("shipping") or {}
        offers.append({
            "item_id": item_id,
            "price": price,
            "original_price": old if old and old > price else None,
            "free_shipping": bool(shipping.get("free_shipping")),
            "available_quantity": item.get("available_quantity"),
            "condition": clean_text(item.get("condition")),
            "seller_id": item.get("seller_id"),
            "url": f"https://www.mercadolivre.com.br/p/{catalog_id}?item_id={quote(item_id)}",
        })
    offers.sort(key=lambda x: (x["price"], not x["free_shipping"]))
    return offers[:10]

def parse_item_api(item_id, access_token):
    _, item = http_get_json(
        f"https://api.mercadolibre.com/items/{quote(item_id)}",
        extra_headers={"Authorization": f"Bearer {access_token}"},
    )
    if not isinstance(item, dict) or not item.get("title"):
        raise ValueError("A API do Mercado Livre não retornou os dados do item.")

    pictures = item.get("pictures") or []
    images = []
    for picture in pictures:
        if isinstance(picture, dict):
            picture_url = picture.get("secure_url") or picture.get("url") or ""
            if picture_url and picture_url not in images:
                images.append(picture_url)
    image = images[0] if images else ""
    image = image or item.get("secure_thumbnail") or item.get("thumbnail") or ""
    if image and image not in images:
        images.insert(0, image)

    features = []
    brand = ""
    ignored = {"GTIN", "EMPTY_GTIN_REASON", "SELLER_SKU", "ITEM_CONDITION"}
    for attr in item.get("attributes") or []:
        if not isinstance(attr, dict):
            continue
        attr_id = clean_text(attr.get("id")).upper()
        name = clean_text(attr.get("name"))
        value = clean_text(attr.get("value_name"))
        if attr_id == "BRAND" and value:
            brand = value
        if attr_id not in ignored and name and value and len(name) < 40 and len(value) < 80:
            features.append(compact_feature(f"{name}: {value}"))
        if len(features) >= 5:
            break

    title = clean_text(item.get("title"))
    price = first_num(item.get("price"))
    old = first_num(item.get("original_price"))
    if old is not None and price is not None and old <= price:
        old = None
    available = item.get("available_quantity")
    availability = "Disponível" if isinstance(available, (int, float)) and available > 0 else "Não informado"

    return {
        "ok": True, "title": title, "price": price, "original_price": old,
        "other_payment_price": price, "pix_price": None,
        "image": image, "images": images, "description": " ".join(features), "brand": brand,
        "category": clean_text(item.get("category_id")), "availability": availability,
        "rating": "", "free_shipping": bool((item.get("shipping") or {}).get("free_shipping")),
        "benefits": features, "summary": make_summary(title, " ".join(features), brand, price, old),
        "final_url": item.get("permalink") or "",
        "item_id": clean_text(item.get("id") or item_id),
        "warning": "Dados carregados pela API oficial. Confirme preço e condições antes de publicar.",
    }


def _match_text(value):
    value = unicodedata.normalize("NFKD", clean_text(value)).encode("ascii", "ignore").decode("ascii")
    return re.sub(r"[^a-z0-9]+", " ", value.lower()).strip()


def _image_fingerprint(value):
    match = re.search(r"(\d{5,}-[A-Z]{3}\d{8,}_\d{6})", str(value or ""), re.I)
    return match.group(1).upper() if match else ""


def find_item_from_affiliate_metadata(title, image, access_token):
    """Locate the exact MLB item exposed only as social-link metadata."""
    if not title or not access_token:
        return ""
    query = quote(clean_text(title)[:180])
    _, payload = http_get_json(
        f"https://api.mercadolibre.com/sites/MLB/search?q={query}&limit=50",
        extra_headers={"Authorization": f"Bearer {access_token}"},
    )
    results = payload.get("results", []) if isinstance(payload, dict) else []
    wanted_title = _match_text(title)
    wanted_image = _image_fingerprint(image)
    best_id, best_score = "", 0.0
    for candidate in results:
        if not isinstance(candidate, dict):
            continue
        item_id = clean_text(candidate.get("id"))
        if not re.fullmatch(r"MLB\d{6,}", item_id, re.I):
            continue
        candidate_title = _match_text(candidate.get("title"))
        title_score = SequenceMatcher(None, wanted_title, candidate_title).ratio() if candidate_title else 0.0
        candidate_image = _image_fingerprint(candidate.get("thumbnail_id") or candidate.get("thumbnail"))
        image_match = bool(wanted_image and candidate_image and wanted_image == candidate_image)
        score = title_score + (2.0 if image_match else 0.0)
        if score > best_score:
            best_id, best_score = item_id.upper(), score
    # Exact picture is conclusive; without it, require a very close title match.
    return best_id if best_score >= 2.0 or best_score >= 0.88 else ""

def find_product_ld(obj):
    if isinstance(obj, dict):
        t = obj.get("@type")
        if t == "Product" or (isinstance(t, list) and "Product" in t):
            return obj
        if "@graph" in obj:
            got = find_product_ld(obj["@graph"])
            if got: return got
        for v in obj.values():
            got = find_product_ld(v)
            if got: return got
    elif isinstance(obj, list):
        for v in obj:
            got = find_product_ld(v)
            if got: return got
    return None

def extract_json_ld(source):
    for m in re.finditer(r'<script[^>]+type=["\']application/ld\+json["\'][^>]*>(.*?)</script>', source, re.I|re.S):
        raw = htmlmod.unescape(m.group(1)).strip()
        try:
            obj = json.loads(raw)
            p = find_product_ld(obj)
            if p: return p
        except Exception:
            pass
    return {}

def meta(source, key, attr="property"):
    pat = rf'<meta[^>]+{attr}=["\']{re.escape(key)}["\'][^>]+content=["\']([^"\']+)["\'][^>]*>'
    m = re.search(pat, source, re.I)
    if not m:
        pat = rf'<meta[^>]+content=["\']([^"\']+)["\'][^>]+{attr}=["\']{re.escape(key)}["\'][^>]*>'
        m = re.search(pat, source, re.I)
    return htmlmod.unescape(m.group(1)) if m else ""

def first_num(v):
    try:
        if v is None: return None
        if isinstance(v, (int,float)): return float(v)
        s = re.sub(r"[^\d,\.]", "", str(v))
        if "," in s and "." in s:
            s = s.replace(".", "").replace(",", ".")
        elif "," in s:
            s = s.replace(",", ".")
        return float(s)
    except Exception:
        return None

def extract_regex_number(source, names):
    for name in names:
        patterns = [
            rf'"{re.escape(name)}"\s*:\s*([0-9]+(?:\.[0-9]+)?)',
            rf'"{re.escape(name)}"\s*:\s*"([0-9]+(?:[.,][0-9]+)?)"',
        ]
        for p in patterns:
            m = re.search(p, source, re.I)
            if m:
                x = first_num(m.group(1))
                if x is not None: return x
    return None

def extract_features(ld):
    out = []
    ap = ld.get("additionalProperty", []) if isinstance(ld, dict) else []
    if isinstance(ap, dict): ap = [ap]
    for x in ap:
        if not isinstance(x, dict): continue
        name = clean_text(x.get("name"))
        val = clean_text(x.get("value"))
        if name and val and len(name) < 40 and len(val) < 80:
            item = compact_feature(f"{name}: {val}")
            if item not in out:
                out.append(item)
        if len(out) >= 4: break
    return out


def extract_shopee_public_features(source):
    """Read brand and attributes embedded in Shopee's public product state."""
    decoder = json.JSONDecoder()
    for marker in re.finditer(r'"attributes"\s*:\s*', source, re.I):
        try:
            attributes, _ = decoder.raw_decode(source[marker.end():])
        except (ValueError, TypeError):
            continue
        if not isinstance(attributes, list):
            continue
        features = []
        for attribute in attributes:
            if not isinstance(attribute, dict):
                continue
            name = clean_text(attribute.get("name"))
            value = clean_text(attribute.get("value"))
            if name and value:
                feature = compact_feature(f"{name}: {value}")
                if feature and feature not in features:
                    features.append(feature)
            if len(features) >= 5:
                break
        if not features:
            continue

        prefix = source[max(0, marker.start() - 20000):marker.start()]
        brand = ""
        brand_matches = list(re.finditer(r'"brand"\s*:\s*"((?:\\.|[^"\\])*)"', prefix, re.I))
        if brand_matches:
            try:
                brand = clean_text(json.loads('"' + brand_matches[-1].group(1) + '"'))
            except (ValueError, TypeError):
                brand = clean_text(brand_matches[-1].group(1))
        return brand, features
    return "", []

def compact_feature(value, max_length=58):
    text = clean_text(value)
    text = re.split(r"\s+(?:ideal\s+para|que garante|para garantir|para organização|para armazenar|oferecem|asseguram)\b", text, maxsplit=1, flags=re.I)[0]
    text = text.rstrip(" ,.;:-")
    if len(text) <= max_length:
        return text
    short = text[:max_length + 1].rsplit(" ", 1)[0].rstrip(" ,.;:-")
    return short or text[:max_length].rstrip()

def make_summary(title, description, brand, price, old):
    text = (title + " " + description).lower()
    if any(k in text for k in ["ferrament", "chave", "soquete", "parafus", "alicate"]):
        base = "Praticidade para o dia a dia."
    elif any(k in text for k in ["cozinha", "panela", "lixeira", "organizador", "casa", "banheiro"]):
        base = "Organização para sua casa."
    elif any(k in text for k in ["limpeza", "aspirador", "extratora", "lava", "limpador"]):
        base = "Limpeza prática."
    elif any(k in text for k in ["fone", "celular", "smartphone", "notebook", "ssd", "monitor"]):
        base = "Tecnologia com economia."
    elif any(k in text for k in ["carro", "automot", "veículo", "veiculo"]):
        base = "Praticidade para seu veículo."
    else:
        base = "Bom custo-benefício."
    if old and price and old > price:
        d = round((old-price)/old*100)
        base += f" {d}% OFF."
    return base


def extract_social_featured_card(source):
    """Read only the product explicitly shared in a Mercado Livre affiliate profile.

    Social pages also contain many recommendations. Reading a generic price or the
    first MLB code from the full document can therefore mix different products.
    The shared product lives in the card-featured component.
    """
    marker = source.find('"id":"card-featured"')
    if marker < 0:
        return None
    polycards = source.find('"polycards":[', marker, marker + 120000)
    if polycards < 0:
        return None
    start = source.find("{", polycards)
    if start < 0:
        return None
    try:
        card, _ = json.JSONDecoder().raw_decode(source[start:])
    except (ValueError, json.JSONDecodeError):
        return None
    if not isinstance(card, dict):
        return None

    metadata = card.get("metadata") or {}
    item_id = clean_text(metadata.get("id")).replace("-", "").upper()
    if not re.fullmatch(r"MLB\d{6,}", item_id):
        return None
    catalog_id = clean_text(metadata.get("product_id")).upper()
    if not re.fullmatch(r"MLB\d{6,}", catalog_id):
        catalog_id = ""
    user_product_id = clean_text(metadata.get("user_product_id")).upper()

    title = ""
    price = None
    old = None
    availability = "Disponível"
    free_shipping = False
    for component in card.get("components") or []:
        if not isinstance(component, dict):
            continue
        component_id = component.get("id")
        if component_id == "title":
            title = clean_text((component.get("title") or {}).get("text"))
        elif component_id == "price":
            price_data = component.get("price") or {}
            price = first_num((price_data.get("current_price") or {}).get("value"))
            old = first_num((price_data.get("previous_price") or {}).get("value"))
        elif component_id == "shipping":
            shipping_text = clean_text((component.get("shipping") or {}).get("text"))
            free_shipping = bool(re.search(r"frete gr[aá]tis", shipping_text, re.I))
        elif component_id == "last_available":
            availability = clean_text((component.get("last_available") or {}).get("text")) or availability
    if old is not None and price is not None and old <= price:
        old = None

    images = []
    for picture in (card.get("pictures") or {}).get("pictures") or []:
        picture_id = clean_text(picture.get("id")) if isinstance(picture, dict) else ""
        if picture_id:
            picture_url = f"https://http2.mlstatic.com/D_NQ_NP_{picture_id}-O.webp"
            if picture_url not in images:
                images.append(picture_url)

    target_url = ""
    url_params = clean_text(metadata.get("url_params"))
    if url_params:
        target_url = (parse_qs(url_params.lstrip("?")).get("url") or [""])[0]
    parsed_target = urlparse(target_url)
    if is_allowed_product_url(target_url, "mercadolivre") and re.search(r"/p/MLB\d{6,}", parsed_target.path, re.I):
        original_url = urlunparse((
            "https", parsed_target.netloc.lower(), parsed_target.path, "",
            urlencode({"item_id": item_id}), "",
        ))
    elif catalog_id:
        original_url = f"https://www.mercadolivre.com.br/p/{catalog_id}?item_id={quote(item_id)}"
    else:
        original_url = f"https://produto.mercadolivre.com.br/MLB-{item_id[3:]}"

    return {
        "ok": True,
        "platform": "mercadolivre",
        "title": title,
        "price": price,
        "original_price": old,
        "image": images[0] if images else "",
        "images": images,
        "description": "",
        "brand": "",
        "category": clean_text(metadata.get("category_id")),
        "availability": availability,
        "rating": "",
        "free_shipping": free_shipping,
        "benefits": [],
        "summary": make_summary(title, "", "", price, old),
        "final_url": original_url,
        "item_id": item_id,
        "catalog_id": catalog_id,
        "user_product_id": user_product_id,
        "warning": "",
    }


def parse_product_page(url, access_token="", affiliate_input=False):
    mobile_headers = None
    if affiliate_input:
        mobile_headers = {
            "User-Agent": "Mozilla/5.0 (Linux; Android 15; Mobile) AppleWebKit/537.36 Chrome/151.0 Mobile Safari/537.36",
            "Referer": "https://www.mercadolivre.com.br/",
        }
    final_url, headers, body = http_get(
        url, extra_headers=mobile_headers,
        redirect_validator=lambda target: is_allowed_product_input_url(target, "mercadolivre"),
    )
    source = body.decode("utf-8", errors="ignore")
    ld = extract_json_ld(source)

    social_card = extract_social_featured_card(source) if affiliate_input else None
    item_id = (social_card or {}).get("item_id") or extract_item_id(url + " " + final_url, source)
    if item_id and access_token:
        try:
            api_result = parse_item_api(item_id, access_token)
            if social_card:
                api_price = first_num(api_result.get("price"))
                social_price = first_num(social_card.get("price"))
                # Price and picture shown by the affiliate link can include a
                # current Pix promotion that is not reflected in items/{id}.
                for key in ("title", "price", "original_price", "image", "images",
                            "availability", "free_shipping", "final_url", "catalog_id",
                            "user_product_id"):
                    value = social_card.get(key)
                    if value not in (None, "", []):
                        api_result[key] = value
                if api_price is not None and social_price is not None and social_price < api_price:
                    api_result["pix_price"] = social_price
                    api_result["other_payment_price"] = api_price
                else:
                    api_result["other_payment_price"] = social_price if social_price is not None else api_price
                api_result["summary"] = make_summary(
                    api_result.get("title", ""), api_result.get("description", ""),
                    api_result.get("brand", ""), api_result.get("price"),
                    api_result.get("original_price"),
                )
                api_result["warning"] = (
                    "Produto exato identificado pelo link de afiliado. "
                    "Preço do link e características da API oficial carregados."
                )
            return api_result
        except (HTTPError, URLError, ValueError, json.JSONDecodeError):
            # Keep the existing HTML parser as a fallback if the API is unavailable.
            pass
    if social_card and access_token and social_card.get("catalog_id"):
        try:
            catalog = parse_catalog_details_api(social_card["catalog_id"], access_token)
            social_images = social_card.get("images") or []
            catalog_images = catalog.get("images") or []
            merged_images = list(dict.fromkeys(social_images + catalog_images))
            social_card.update({
                "brand": catalog.get("brand") or social_card.get("brand", ""),
                "description": catalog.get("description") or social_card.get("description", ""),
                "benefits": catalog.get("benefits") or social_card.get("benefits", []),
                "images": merged_images,
                "other_payment_price": social_card.get("price"),
                "pix_price": None,
            })
            if not social_card.get("category"):
                social_card["category"] = catalog.get("category", "")
            if not social_card.get("image") and merged_images:
                social_card["image"] = merged_images[0]
            social_card["summary"] = make_summary(
                social_card.get("title", ""), social_card.get("description", ""),
                social_card.get("brand", ""), social_card.get("price"),
                social_card.get("original_price"),
            )
            social_card["warning"] = (
                "Produto e preço exatos identificados pelo link de afiliado. "
                "Características carregadas pelo catálogo oficial do Mercado Livre."
            )
            return social_card
        except (HTTPError, URLError, ValueError, json.JSONDecodeError):
            pass
    if social_card:
        social_card["other_payment_price"] = social_card.get("price")
        social_card["pix_price"] = None
        social_card["warning"] = (
            "Produto e preço exatos identificados pelo link de afiliado. "
            "Conecte novamente o Mercado Livre para carregar as características oficiais."
            if not access_token else
            "Produto e preço exatos identificados, mas a API do Mercado Livre não retornou as características."
        )
        return social_card
    catalog_id = extract_catalog_id(url) or extract_catalog_id(final_url)
    if catalog_id and access_token:
        try:
            return parse_catalog_api(catalog_id, access_token)
        except (HTTPError, URLError, ValueError, json.JSONDecodeError):
            pass
    user_product_id = extract_user_product_id(url) or extract_user_product_id(final_url)

    title = clean_text(ld.get("name")) or clean_text(meta(source, "og:title")) or clean_text(meta(source, "twitter:title", "name"))
    image = ""
    images = []
    imgs = ld.get("image") if isinstance(ld, dict) else None
    if isinstance(imgs, list):
        images = [value for value in imgs if isinstance(value, str) and value]
        image = images[0] if images else ""
    elif isinstance(imgs, str):
        image = imgs
        images = [imgs]
    image = image or meta(source, "og:image") or meta(source, "twitter:image", "name")
    if image and image not in images:
        images.insert(0, image)

    if affiliate_input and not item_id and not catalog_id and not canonicalize_product_url(final_url, "mercadolivre"):
        try:
            recovered_item_id = find_item_from_affiliate_metadata(title, image, access_token)
            if recovered_item_id:
                recovered = parse_item_api(recovered_item_id, access_token)
                recovered["resolved_via_search"] = True
                return recovered
        except (HTTPError, URLError, ValueError, json.JSONDecodeError):
            pass

    description = clean_text(ld.get("description")) or clean_text(meta(source, "description", "name"))
    brand = ""
    b = ld.get("brand") if isinstance(ld, dict) else None
    if isinstance(b, dict): brand = clean_text(b.get("name"))
    elif b: brand = clean_text(b)

    offers = ld.get("offers", {}) if isinstance(ld, dict) else {}
    if isinstance(offers, list): offers = offers[0] if offers else {}
    price = first_num(offers.get("price")) or first_num(offers.get("lowPrice"))
    if price is None:
        p = meta(source, "product:price:amount")
        price = first_num(p) if p else None
    if price is None:
        price = extract_regex_number(source, ["price", "base_price"])

    old = extract_regex_number(source, ["original_price", "originalPrice", "list_price", "old_price"])
    if old is not None and price is not None and old <= price:
        old = None

    availability = clean_text(offers.get("availability"))
    availability = availability.rsplit("/",1)[-1] if availability else ""
    if availability.lower() in ("instock","in stock"): availability = "Disponível"
    elif availability.lower() in ("outofstock","out of stock"): availability = "Sem estoque"

    rating = ""
    ar = ld.get("aggregateRating", {}) if isinstance(ld, dict) else {}
    if isinstance(ar, dict) and ar.get("ratingValue"): rating = str(ar.get("ratingValue"))

    features = extract_features(ld)
    if brand and not any("marca:" in x.lower() for x in features):
        features.insert(0, f"Marca: {brand}")
    # Useful properties from title/description without inventing.
    if "pedal" in (title+" "+description).lower() and not any("pedal" in x.lower() for x in features):
        features.append("Abertura por pedal")
    if "remov" in (title+" "+description).lower() and not any("remov" in x.lower() for x in features):
        features.append("Parte interna removível")
    features = features[:5]

    free_shipping = bool(re.search(r'frete gr[aá]tis|free_shipping"\s*:\s*true', source, re.I))
    category = clean_text(ld.get("category")) if isinstance(ld, dict) else ""

    warning = ""
    if not title:
        if user_product_id:
            title = title_from_product_url(url)
            warning = "Este link é uma página MLBU de outro vendedor. A API oficial não libera preço e foto; abra o produto e copie o link do anúncio individual que contenha um item MLB."
        else:
            warning = "O Mercado Livre bloqueou a leitura automática desta página. Confira a conexão OAuth ou complete os campos manualmente."
    elif price is None:
        warning = "Produto encontrado, mas o preço não pôde ser lido automaticamente. Informe o preço antes de publicar."

    return {
        "ok": True,
        "title": title,
        "price": price,
        "original_price": old,
        "image": image,
        "images": images,
        "description": description,
        "brand": brand,
        "category": category,
        "availability": availability or "Não informado",
        "rating": rating,
        "free_shipping": free_shipping,
        "benefits": features,
        "summary": make_summary(title, description, brand, price, old),
        "final_url": final_url,
        "user_product_id": user_product_id,
        "warning": warning,
    }

def extract_shopee_images(source, ld, fallback=""):
    found = []

    def add(value):
        if not isinstance(value, str):
            return
        value = htmlmod.unescape(value).replace("\\/", "/").replace("\\u002F", "/").strip()
        if value.startswith("//"):
            value = "https:" + value
        if value.startswith("http") and is_allowed_image_url(value) and value not in found:
            found.append(value)

    ld_images = ld.get("image") if isinstance(ld, dict) else None
    if isinstance(ld_images, list):
        for value in ld_images:
            add(value)
    else:
        add(ld_images)
    add(fallback)

    decoded = htmlmod.unescape(source).replace("\\/", "/").replace("\\u002F", "/")
    for match in re.finditer(r'https?://[^"\'<>\s,}]+(?:susercontent\.com|shopee\.com\.br)/[^"\'<>\s,}]+', decoded, re.I):
        add(match.group(0))
        if len(found) >= 20:
            break

    # Shopee frequently stores product images as CDN file identifiers instead of full URLs.
    for block in re.findall(r'"images"\s*:\s*\[(.{0,5000}?)\]', decoded, re.I | re.S):
        for file_id in re.findall(r'"([A-Za-z0-9_-]{20,})"', block):
            add(f"https://down-br.img.susercontent.com/file/{file_id}")
            if len(found) >= 20:
                return found
    for file_id in re.findall(r'"(?:image|cover|cover_image)"\s*:\s*"([A-Za-z0-9_-]{20,})"', decoded, re.I):
        add(f"https://down-br.img.susercontent.com/file/{file_id}")
        if len(found) >= 20:
            break
    return found

def parse_shopee_page(url, affiliate_input=False):
    # Short affiliate links return an intermediate shell to mobile user agents,
    # without the product URL or metadata. The desktop user agent used by
    # http_get receives the canonical product redirect.
    request_headers = {"Referer": "https://shopee.com.br/"} if affiliate_input else None
    final_url, headers, body = http_get(
        url, extra_headers=request_headers,
        redirect_validator=lambda target: is_allowed_product_input_url(target, "shopee"),
    )
    if not is_allowed_product_url(final_url, "shopee"):
        raise ValueError("O link redirecionou para um endereço fora da Shopee.")

    # Current short links can land on /store-slug/shop_id/item_id. That page is
    # only an app shell. The stable /product route exposes the public metadata.
    product_ids = shopee_product_ids(final_url)
    if affiliate_input and product_ids and not re.search(r"(?:-i\.\d+\.\d+|/product/\d+/\d+)", urlparse(final_url).path, re.I):
        shop_id, item_id = product_ids
        lookup_url = f"https://shopee.com.br/product/{shop_id}/{item_id}"
        try:
            final_url, headers, body = http_get(
                lookup_url,
                extra_headers={"Referer": final_url},
                redirect_validator=lambda target: is_allowed_product_input_url(target, "shopee"),
            )
        except (HTTPError, URLError, TimeoutError):
            pass

    source = body.decode("utf-8", errors="ignore")
    public_url = meta(source, "og:url")
    if is_allowed_product_url(public_url, "shopee") and shopee_product_ids(public_url):
        final_url = public_url
    ld = extract_json_ld(source)

    title = clean_text(ld.get("name")) or clean_text(meta(source, "og:title")) or clean_text(meta(source, "twitter:title", "name"))
    title = re.sub(r"\s*[|\-]\s*Shopee Brasil\s*$", "", title, flags=re.I).strip()
    if not title:
        title = title_from_shopee_url(final_url) or title_from_shopee_url(url)

    fallback_image = meta(source, "og:image") or meta(source, "twitter:image", "name")
    images = extract_shopee_images(source, ld, fallback_image)
    image = images[0] if images else fallback_image

    description = clean_text(ld.get("description")) or clean_text(meta(source, "description", "name"))
    embedded_brand, embedded_features = extract_shopee_public_features(source)
    offers = ld.get("offers", {}) if isinstance(ld, dict) else {}
    if isinstance(offers, list):
        offers = offers[0] if offers else {}
    price = first_num(offers.get("price")) or first_num(offers.get("lowPrice"))
    if price is None:
        price = first_num(meta(source, "product:price:amount")) or first_num(meta(source, "og:price:amount"))
    old = first_num(offers.get("highPrice")) or first_num(meta(source, "product:original_price:amount"))
    if old is not None and price is not None and old <= price:
        old = None

    availability = clean_text(offers.get("availability"))
    availability = availability.rsplit("/", 1)[-1] if availability else ""
    if availability.lower() in ("instock", "in stock"):
        availability = "Disponível"
    elif availability.lower() in ("outofstock", "out of stock"):
        availability = "Sem estoque"

    brand = ""
    brand_data = ld.get("brand") if isinstance(ld, dict) else None
    if isinstance(brand_data, dict):
        brand = clean_text(brand_data.get("name"))
    elif brand_data:
        brand = clean_text(brand_data)
    if not brand:
        brand = embedded_brand
    features = extract_features(ld)[:5]
    for feature in embedded_features:
        if feature not in features:
            features.append(feature)
        if len(features) >= 5:
            break
    if brand and not any("marca:" in item.lower() for item in features):
        features.insert(0, f"Marca: {brand}")
    features = features[:5]

    rating = ""
    aggregate = ld.get("aggregateRating", {}) if isinstance(ld, dict) else {}
    if isinstance(aggregate, dict) and aggregate.get("ratingValue"):
        rating = str(aggregate.get("ratingValue"))

    warning = ""
    if price is None or not image:
        warning = "A Shopee não expôs todos os dados desta página. Confira o preço e complete os campos que ficaram vazios."
    return {
        "ok": True,
        "platform": "shopee",
        "title": title,
        "price": price,
        "original_price": old,
        "image": image,
        "images": images,
        "description": description,
        "brand": brand,
        "category": clean_text(ld.get("category")) if isinstance(ld, dict) else "",
        "availability": availability or "Não informado",
        "rating": rating,
        "free_shipping": bool(re.search(r"frete gr[aá]tis", source, re.I)),
        "benefits": features,
        "summary": make_summary(title, description, brand, price, old),
        "final_url": final_url,
        "warning": warning,
    }


def extract_amazon_images(source, ld, fallback=""):
    found = []

    def add(value):
        if not isinstance(value, str):
            return
        value = htmlmod.unescape(value).replace("\\/", "/").strip()
        if value.startswith("//"):
            value = "https:" + value
        if value.startswith("https://") and is_allowed_image_url(value) and value not in found:
            found.append(value)

    ld_images = ld.get("image") if isinstance(ld, dict) else None
    if isinstance(ld_images, list):
        for value in ld_images:
            add(value)
    else:
        add(ld_images)
    add(fallback)

    decoded = htmlmod.unescape(source).replace("\\/", "/")
    marker = decoded.find("colorImages")
    image_block = decoded[marker:marker + 180000] if marker >= 0 else ""
    for match in re.finditer(
        r'"hiRes"\s*:\s*(?:"([^"]+)"|null).{0,700}?"large"\s*:\s*"([^"]+)"',
        image_block, re.I | re.S,
    ):
        add(match.group(1) or match.group(2))
        if len(found) >= 20:
            break
    if not found:
        dynamic = re.search(r'id=["\']landingImage["\'][^>]+data-a-dynamic-image=["\'](.*?)["\']', decoded, re.I | re.S)
        if dynamic:
            candidates = re.findall(r'(https://[^"\'\s]+(?:\.jpg|\.jpeg|\.png|\.webp))', dynamic.group(1), re.I)
            if candidates:
                add(candidates[-1])
    return found


def _amazon_element_text(source, element_id):
    match = re.search(
        rf'<[^>]+id=["\']{re.escape(element_id)}["\'][^>]*>(.*?)</[^>]+>',
        source, re.I | re.S,
    )
    return clean_text(match.group(1)) if match else ""


def _amazon_price(source, old=False):
    ids = (
        ("priceblock_listprice", "basisPrice", "listPrice") if old else
        ("priceblock_dealprice", "priceblock_ourprice", "priceToPay", "priceAmount")
    )
    for marker in ids:
        text = _amazon_element_text(source, marker)
        value = first_num(text)
        if value is not None:
            return value
        patterns = (
            rf'"{re.escape(marker)}"\s*:\s*\{{[^}}]{{0,500}}?"amount"\s*:\s*([0-9.]+)',
            rf'"{re.escape(marker)}"\s*:\s*([0-9.]+)',
        )
        for pattern in patterns:
            match = re.search(pattern, source, re.I | re.S)
            if match:
                value = first_num(match.group(1))
                if value is not None:
                    return value
    if not old:
        match = re.search(r'<span[^>]+class=["\'][^"\']*a-offscreen[^"\']*["\'][^>]*>\s*(R\$\s*[0-9.,]+)', source, re.I)
        if match:
            return first_num(match.group(1))
    return None


def parse_amazon_page(url, affiliate_input=False):
    final_url, headers, body = http_get(
        url,
        extra_headers={"Referer": "https://www.amazon.com.br/"} if affiliate_input else None,
        redirect_validator=lambda target: is_allowed_product_input_url(target, "amazon"),
    )
    final_host = _safe_https_host(final_url)
    if final_host in {"amzlinks.in", "www.amzlinks.in"}:
        bridge_source = htmlmod.unescape(body.decode("utf-8", errors="ignore")).replace("\\/", "/")
        bridge_match = re.search(
            r'window\.location\.(?:replace|assign)\(\s*["\'](https://[^"\']+)["\']\s*\)',
            bridge_source, re.I,
        )
        bridge_url = bridge_match.group(1) if bridge_match else ""
        if not is_allowed_product_url(bridge_url, "amazon"):
            raise ValueError("O link curto não informou um produto válido da Amazon Brasil.")
        final_url, headers, body = http_get(
            bridge_url,
            extra_headers={"Referer": final_url},
            redirect_validator=lambda target: is_allowed_product_input_url(target, "amazon"),
        )
    if not is_allowed_product_url(final_url, "amazon"):
        raise ValueError("O link redirecionou para um endereço fora da Amazon.")

    source = body.decode("utf-8", errors="ignore")
    ld = extract_json_ld(source)
    asin = extract_amazon_asin(final_url, source) or extract_amazon_asin(url)
    title = clean_text(ld.get("name")) if isinstance(ld, dict) else ""
    title = title or _amazon_element_text(source, "productTitle")
    title = title or clean_text(meta(source, "og:title")) or clean_text(meta(source, "twitter:title", "name"))

    fallback_image = meta(source, "og:image") or meta(source, "twitter:image", "name")
    images = extract_amazon_images(source, ld, fallback_image)
    image = images[0] if images else fallback_image

    offers = ld.get("offers", {}) if isinstance(ld, dict) else {}
    if isinstance(offers, list):
        offers = offers[0] if offers else {}
    price = first_num(offers.get("price")) or first_num(offers.get("lowPrice"))
    if price is None:
        price = first_num(meta(source, "product:price:amount")) or _amazon_price(source)
    old = first_num(offers.get("highPrice")) or _amazon_price(source, old=True)
    if old is not None and price is not None and old <= price:
        old = None

    description = clean_text(ld.get("description")) if isinstance(ld, dict) else ""
    features = extract_features(ld)[:5]
    bullets = re.search(
        r'id=["\']feature-bullets["\'](.*?)(?:id=["\']productOverview|id=["\']aplus|</ul>)',
        source, re.I | re.S,
    )
    if bullets:
        for item in re.findall(r'<li[^>]*>(.*?)</li>', bullets.group(1), re.I | re.S):
            value = compact_feature(clean_text(item))
            if value and len(value) <= 180 and value not in features:
                features.append(value)
            if len(features) >= 5:
                break
    features = features[:5]
    if not description:
        description = " ".join(features)

    brand = ""
    brand_data = ld.get("brand") if isinstance(ld, dict) else None
    if isinstance(brand_data, dict):
        brand = clean_text(brand_data.get("name"))
    elif brand_data:
        brand = clean_text(brand_data)
    if not brand:
        brand = re.sub(r"^(?:Visite a loja |Marca: )", "", _amazon_element_text(source, "bylineInfo"), flags=re.I)
    if brand and not any("marca:" in value.lower() for value in features):
        features.insert(0, f"Marca: {brand}")
        features = features[:5]

    availability = clean_text(offers.get("availability")) if isinstance(offers, dict) else ""
    availability = availability.rsplit("/", 1)[-1] if availability else _amazon_element_text(source, "availability")
    if availability.lower() in ("instock", "in stock"):
        availability = "Disponível"
    elif availability.lower() in ("outofstock", "out of stock"):
        availability = "Sem estoque"

    rating = ""
    aggregate = ld.get("aggregateRating", {}) if isinstance(ld, dict) else {}
    if isinstance(aggregate, dict) and aggregate.get("ratingValue"):
        rating = str(aggregate.get("ratingValue"))

    final_product_url = f"https://www.amazon.com.br/dp/{asin}" if asin else final_url
    missing = []
    if not title:
        missing.append("nome")
    if price is None:
        missing.append("preço")
    if not image:
        missing.append("foto")
    warning = ""
    if missing:
        warning = (
            "A Amazon não expôs automaticamente " + ", ".join(missing) +
            " deste produto. Confira e complete os campos que ficaram vazios."
        )
    return {
        "ok": True, "platform": "amazon", "title": title,
        "price": price, "original_price": old, "image": image, "images": images,
        "description": description, "brand": brand,
        "category": clean_text(ld.get("category")) if isinstance(ld, dict) else "",
        "availability": availability or "Não informado", "rating": rating,
        "free_shipping": bool(re.search(r"frete gr[aá]tis", source, re.I)),
        "benefits": features,
        "summary": make_summary(title, description, brand, price, old),
        "final_url": final_product_url, "asin": asin, "warning": warning,
    }


def parse_product_input(url, platform="mercadolivre", access_token=""):
    """Resolve original and affiliate product URLs while preserving commission."""
    affiliate_input = is_affiliate_product_url(url, platform)
    if platform == "shopee":
        result = parse_shopee_page(url, affiliate_input=affiliate_input)
    elif platform == "amazon":
        result = parse_amazon_page(url, affiliate_input=affiliate_input)
    else:
        result = parse_product_page(url, access_token, affiliate_input=affiliate_input)

    original_url = canonicalize_product_url(result.get("final_url", ""), platform)
    if not original_url:
        original_url = canonicalize_product_url(url, platform)

    result["platform"] = platform
    result["input_url"] = url
    result["original_url"] = original_url
    result["affiliate_url"] = url if affiliate_input else ""
    result["resolved_from_affiliate"] = affiliate_input
    if affiliate_input and original_url:
        result["link_notice"] = (
            "Link de afiliado reconhecido. Produto original localizado e "
            "link com comissão inserido automaticamente."
        )
    elif affiliate_input:
        result["link_notice"] = "Link de afiliado reconhecido e preservado para a publicação."
        unresolved = (
            "Não foi possível confirmar automaticamente o endereço original exato deste produto. "
            "Confira os dados antes de publicar."
        )
        result["warning"] = " ".join(filter(None, (result.get("warning", ""), unresolved)))
    else:
        result["link_notice"] = ""
    return result

