def configured_users():
    users = {}
    for number in (1, 2):
        username = os.environ.get(f"APP_USER_{number}", "").strip()
        password = os.environ.get(f"APP_PASSWORD_{number}", "")
        if username and password:
            users[username] = password
    return users


def auth_required():
    return IS_RENDER or bool(configured_users())


def configuration_errors():
    if not IS_RENDER:
        return []
    missing = []
    required = ("DATABASE_URL", "TOKEN_ENCRYPTION_KEY", "APP_SESSION_SECRET",
                "APP_USER_1", "APP_PASSWORD_1", "APP_USER_2", "APP_PASSWORD_2",
                "MELI_CLIENT_ID", "MELI_CLIENT_SECRET")
    for name in required:
        if not os.environ.get(name, "").strip():
            missing.append(name)
    if not (os.environ.get("MELI_REDIRECT_URI", "").strip()
            or os.environ.get("PUBLIC_BASE_URL", "").strip()):
        missing.append("PUBLIC_BASE_URL")
    return missing


def _b64url_encode(data):
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _b64url_decode(value):
    return base64.urlsafe_b64decode(value + "=" * (-len(value) % 4))


def create_session_token(username):
    payload = json.dumps({"u": username, "exp": int(time.time()) + SESSION_TTL},
                         separators=(",", ":")).encode("utf-8")
    encoded = _b64url_encode(payload)
    signature = _b64url_encode(hmac.new(SESSION_SECRET.encode("utf-8"), encoded.encode("ascii"),
                                        hashlib.sha256).digest())
    return f"{encoded}.{signature}"


def verify_session_token(token):
    try:
        encoded, supplied = token.split(".", 1)
        expected = _b64url_encode(hmac.new(SESSION_SECRET.encode("utf-8"), encoded.encode("ascii"),
                                           hashlib.sha256).digest())
        if not secrets.compare_digest(supplied, expected):
            return ""
        payload = json.loads(_b64url_decode(encoded).decode("utf-8"))
        username = str(payload.get("u", ""))
        if int(payload.get("exp", 0)) <= int(time.time()) or username not in configured_users():
            return ""
        return username
    except Exception:
        return ""


def safe_local_next(value):
    """Keep login redirects inside the generator and preserve shared product data."""
    value = str(value or "").strip()
    if not value or len(value) > 8192 or any(ord(char) < 32 for char in value):
        return "/"
    parsed = urlparse(value)
    if parsed.scheme or parsed.netloc or parsed.path not in ("/", "/receive-share"):
        return "/"
    return parsed.path + (("?" + parsed.query) if parsed.query else "")


def oauth_result_html(ok, message):
    safe = htmlmod.escape(message)
    color = "#8ee000" if ok else "#ff8b8b"
    script = "" if not ok else """
    <script>if(window.opener){window.opener.postMessage({type:'meli-oauth-complete'},window.location.origin);setTimeout(()=>window.close(),900)}</script>
    """
    return f"""<!doctype html><html lang='pt-BR'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Mercado Livre</title></head>
    <body style='font-family:Arial;background:#07152f;color:white;display:grid;place-items:center;min-height:100vh;margin:0;text-align:center;padding:24px'><div><h2 style='color:{color}'>{safe}</h2><p>Você já pode fechar esta janela e voltar ao gerador.</p><a href='/' style='color:#ffd500'>Voltar ao gerador</a></div>{script}</body></html>"""


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def send_json(self, obj, status=200, extra_headers=None):
        data = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        for name, value in (extra_headers or {}).items():
            self.send_header(name, value)
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def send_html(self, content, status=200):
        data = content.encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def redirect(self, location):
        self.send_response(302)
        self.send_header("Location", location)
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", "0")
        self.end_headers()

    def current_user(self):
        if not auth_required():
            return "local"
        cookie = SimpleCookie()
        try:
            cookie.load(self.headers.get("Cookie", ""))
            morsel = cookie.get(SESSION_COOKIE)
            return verify_session_token(morsel.value) if morsel else ""
        except Exception:
            return ""

    def require_auth(self, api=False, next_path=""):
        if self.current_user():
            return True
        if api:
            self.send_json({"ok": False, "error": "Sessão expirada. Entre novamente."}, 401)
        else:
            destination = safe_local_next(next_path)
            self.redirect("/login?next=" + quote(destination, safe=""))
        return False

    def request_is_same_origin(self):
        if self.headers.get("Sec-Fetch-Site", "").lower() == "cross-site":
            return False
        origin = self.headers.get("Origin", "").rstrip("/")
        if not origin:
            return True
        proto = self.headers.get("X-Forwarded-Proto", "http").split(",", 1)[0].strip()
        host = self.headers.get("Host", "")
        return secrets.compare_digest(origin, f"{proto}://{host}")

    def read_json(self):
        try:
            size = int(self.headers.get("Content-Length", "0"))
        except ValueError:
            size = 0
        if size < 0 or size > 64 * 1024:
            raise ValueError("Requisição muito grande.")
        return json.loads(self.rfile.read(size).decode("utf-8")) if size else {}

    def do_GET(self):
        parsed = urlparse(self.path)
        if parsed.path == "/health":
            errors = configuration_errors()
            return self.send_json({"ok": True, "ready": not errors,
                                   "missing_configuration": errors,
                                   "storage": "postgresql" if meli_auth.using_database() else "local",
                                   "oauth_redirect_uri": meli_auth.configured_redirect_uri()})

        if parsed.path == "/manifest.webmanifest":
            data = json.dumps(PWA_MANIFEST, ensure_ascii=False).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/manifest+json; charset=utf-8")
            self.send_header("Cache-Control", "no-cache")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
            return

        if parsed.path == "/service-worker.js":
            data = SERVICE_WORKER.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/javascript; charset=utf-8")
            self.send_header("Cache-Control", "no-cache")
            self.send_header("Service-Worker-Allowed", "/")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
            return

        if parsed.path == "/logo.png":
            data = base64.b64decode(LOGO_B64)
            self.send_response(200)
            self.send_header("Content-Type", "image/png")
            self.send_header("Cache-Control", "public, max-age=86400")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
            return

        if parsed.path in ("/icon-192.png", "/icon-512.png"):
            icon_path = Path(__file__).resolve().parent / parsed.path.lstrip("/")
            try:
                data = icon_path.read_bytes()
            except OSError:
                self.send_error(404, "Ícone não encontrado")
                return
            self.send_response(200)
            self.send_header("Content-Type", "image/png")
            self.send_header("Cache-Control", "public, max-age=86400")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
            return

        if parsed.path == "/login":
            if self.current_user() and auth_required():
                return self.redirect(safe_local_next(parse_qs(parsed.query).get("next", [""])[0]))
            return self.send_html(LOGIN_HTML)

        if not self.require_auth(api=parsed.path.startswith("/api/"), next_path=self.path):
            return

        if parsed.path == "/api/session":
            username = self.current_user()
            return self.send_json({"ok": True, "username": "" if username == "local" else username})

        if parsed.path == "/oauth/callback":
            query = parse_qs(parsed.query)
            oauth_error = (query.get("error_description") or query.get("error") or [""])[0]
            if oauth_error:
                return self.send_html(oauth_result_html(False, f"Autorização recusada: {oauth_error}"), 400)
            code = (query.get("code") or [""])[0]
            state = (query.get("state") or [""])[0]
            try:
                meli_auth.complete_authorization_params(code, state)
                return self.send_html(oauth_result_html(True, "Mercado Livre conectado com sucesso"))
            except (ValueError, RuntimeError, PermissionError) as error:
                return self.send_html(oauth_result_html(False, str(error)), 400)
            except Exception:
                return self.send_html(oauth_result_html(False, "Falha interna ao concluir a autorização."), 500)

        if parsed.path in ("/", "/receive-share"):
            data = HTML.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Cache-Control", "no-store, no-cache, must-revalidate")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
            return

        if parsed.path == "/api/product":
            query = parse_qs(parsed.query)
            raw_url = query.get("url", [""])[0].strip()
            if len(raw_url) > 4096:
                return self.send_json({"ok": False, "error": "O link informado é muito longo."}, 400)
            url = extract_product_input_url(raw_url)
            platform = query.get("platform", ["mercadolivre"])[0].strip().lower()
            if platform not in ("mercadolivre", "shopee", "amazon"):
                return self.send_json({"ok": False, "error": "Plataforma inválida."}, 400)
            access_token = ""
            if platform == "mercadolivre":
                try:
                    access_token = meli_auth.get_valid_access_token()
                except Exception:
                    pass
            if not url or not is_allowed_product_input_url(url, platform):
                marketplace = "Shopee" if platform == "shopee" else "Amazon" if platform == "amazon" else "Mercado Livre"
                return self.send_json({
                    "ok": False,
                    "error": f"Use um link original ou de afiliado válido do {marketplace}.",
                }, 400)
            try:
                result = parse_product_input(url, platform, access_token)
                return self.send_json(result)
            except HTTPError as e:
                service = "A Shopee" if platform == "shopee" else "A Amazon" if platform == "amazon" else "O Mercado Livre"
                return self.send_json({"ok": False, "error": f"{service} respondeu com erro HTTP {e.code}. Tente novamente ou complete os campos manualmente."}, 502)
            except URLError as e:
                service = "a Shopee" if platform == "shopee" else "a Amazon" if platform == "amazon" else "o Mercado Livre"
                return self.send_json({"ok": False, "error": f"Não foi possível acessar {service} pela sua conexão."}, 502)
            except Exception as e:
                return self.send_json({"ok":False,"error":f"Falha ao interpretar a página: {e}"}, 500)

        if parsed.path == "/api/oauth/status":
            try:
                return self.send_json({"ok": True, **meli_auth.token_status()})
            except Exception as e:
                return self.send_json({"ok": False, "connected": False, "error": str(e)}, 500)

        if parsed.path == "/api/alternatives":
            catalog_id = parse_qs(parsed.query).get("catalog_id", [""])[0].strip().upper()
            if not re.fullmatch(r"MLB\d{6,}", catalog_id):
                return self.send_json({"ok": False, "error": "Código de catálogo inválido."}, 400)
            try:
                token = meli_auth.get_valid_access_token()
                return self.send_json({"ok": True, "offers": find_catalog_offers(catalog_id, token)})
            except Exception as e:
                return self.send_json({"ok": False, "error": f"Falha ao comparar ofertas: {e}"}, 502)

        if parsed.path == "/api/image":
            url = parse_qs(parsed.query).get("url", [""])[0].strip()
            if not url or not is_allowed_image_url(url):
                self.send_error(400, "Imagem não permitida")
                return
            try:
                image_host = (urlparse(url).hostname or "").lower()
                if "shopee" in image_host or "susercontent.com" in image_host:
                    image_headers = {"Referer": "https://shopee.com.br/"}
                elif "amazon" in image_host:
                    image_headers = {"Referer": "https://www.amazon.com.br/"}
                else:
                    image_headers = None
                final, headers, body = http_get(url, accept="image/avif,image/webp,image/apng,image/*,*/*;q=0.8", timeout=45, extra_headers=image_headers)
                if not is_allowed_image_url(final):
                    self.send_error(400, "Redirecionamento de imagem não permitido")
                    return
                ctype = headers.get_content_type() or "image/jpeg"
                if not ctype.startswith("image/"):
                    ctype = detect_image_content_type(body)
                    if not ctype:
                        self.send_error(502, "O endereço não retornou uma imagem")
                        return
                self.send_response(200)
                self.send_header("Content-Type", ctype)
                self.send_header("Cache-Control", "public, max-age=3600")
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)
            except Exception:
                self.send_error(502, "Falha ao carregar imagem")
            return

        self.send_error(404)

    def do_POST(self):
        parsed = urlparse(self.path)
        try:
            payload = self.read_json()
            if parsed.path == "/api/login":
                if not self.request_is_same_origin():
                    return self.send_json({"ok": False, "error": "Origem da requisição não permitida."}, 403)
                errors = configuration_errors()
                if errors:
                    return self.send_json({"ok": False, "error": "Faltam configurações no Render: " + ", ".join(errors)}, 503)
                username = str(payload.get("username", "")).strip()
                password = str(payload.get("password", ""))
                expected = configured_users().get(username)
                valid = expected is not None and secrets.compare_digest(
                    password.encode("utf-8"), expected.encode("utf-8"))
                if not valid:
                    return self.send_json({"ok": False, "error": "Usuário ou senha inválidos."}, 401)
                secure = (self.headers.get("X-Forwarded-Proto", "").split(",", 1)[0].strip() == "https") or IS_RENDER
                cookie = (f"{SESSION_COOKIE}={create_session_token(username)}; Path=/; Max-Age={SESSION_TTL}; "
                          f"HttpOnly; SameSite=Lax" + ("; Secure" if secure else ""))
                return self.send_json({"ok": True, "username": username}, extra_headers={"Set-Cookie": cookie})

            if not self.require_auth(api=True):
                return
            if not self.request_is_same_origin():
                return self.send_json({"ok": False, "error": "Origem da requisição não permitida."}, 403)
            if parsed.path == "/api/logout":
                cookie = f"{SESSION_COOKIE}=; Path=/; Max-Age=0; HttpOnly; SameSite=Lax"
                return self.send_json({"ok": True}, extra_headers={"Set-Cookie": cookie})
            if parsed.path == "/api/oauth/start":
                auth_url = meli_auth.start_authorization(
                    str(payload.get("client_id", "")), str(payload.get("client_secret", "")),
                    str(payload.get("redirect_uri", "")),
                )
                redirect_uri = meli_auth.configured_redirect_uri() or str(payload.get("redirect_uri", ""))
                return self.send_json({"ok": True, "authorization_url": auth_url,
                                       "automatic_callback": redirect_uri.rstrip("/").endswith("/oauth/callback")})
            if parsed.path == "/api/oauth/complete":
                meli_auth.complete_authorization(str(payload.get("callback_url", "")))
                user = meli_auth.get_current_user()
                return self.send_json({"ok": True, "nickname": user.get("nickname"), "user_id": user.get("id")})
            if parsed.path == "/api/oauth/refresh":
                meli_auth.refresh_access_token(force=True)
                return self.send_json({"ok": True})
            if parsed.path == "/api/oauth/disconnect":
                meli_auth.delete_all_credentials()
                return self.send_json({"ok": True})
            return self.send_json({"ok": False, "error": "Rota não encontrada."}, 404)
        except (ValueError, RuntimeError, PermissionError) as e:
            return self.send_json({"ok": False, "error": str(e)}, 400)
        except Exception:
            return self.send_json({"ok": False, "error": "Falha interna na autorização."}, 500)

def open_browser():
    time.sleep(1.0)
    webbrowser.open(f"http://127.0.0.1:{PORT}/")

if __name__ == "__main__":
    print("="*62)
    print(" Entrou, Economizou - Gerador Automático")
    print("="*62)
    print(f"Servidor: http://{HOST}:{PORT}/")
    if meli_auth.using_database():
        meli_auth.ensure_database_schema()
        print("PostgreSQL conectado e tabelas verificadas.")
    if not IS_RENDER and os.environ.get("OPEN_BROWSER", "1") != "0":
        threading.Thread(target=open_browser, daemon=True).start()
    try:
        ThreadingHTTPServer((HOST, PORT), Handler).serve_forever()
    except KeyboardInterrupt:
        print("\nGerador encerrado.")
